package com.example.sample.feature.${feature}.component

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.compose.ui.tooling.preview.Preview
import com.example.sample.ui.preview.PreviewRoot

/** Part of the ${feature} screen that no other screen uses. */
@Composable
internal fun ${name}(
    title: String,
    modifier: Modifier = Modifier,
) {
    Column(
        modifier = modifier,
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        Text(text = title, style = MaterialTheme.typography.titleMedium)
    }
}

@Preview(showBackground = true)
@Composable
private fun ${name}Preview() = PreviewRoot {
    ${name}(title = "${name}")
}

package com.example.sample.feature.home

import com.example.sample.testing.FakeUserRepository
import com.example.sample.ui.core.UiState
import org.junit.Assert.assertEquals
import org.junit.Test

class Home${name}Test {
    @Test
        fun `exposes the value read from the repository as Content`() {
        val viewModel = HomeViewModel(userRepository = FakeUserRepository(userName = "katachi"))

        assertEquals(UiState.Content(HomeContent(userName = "katachi", visitCount = 1)), viewModel.uiState.value)
    }
}

package com.example.sample.feature.settings

import com.example.sample.testing.FakeSettingsRepository
import com.example.sample.ui.core.UiState
import org.junit.Assert.assertEquals
import org.junit.Test

class Settings${name}Test {
    @Test
        fun `exposes the value read from the repository as Content`() {
        val viewModel = SettingsViewModel(settingsRepository = FakeSettingsRepository(darkThemeEnabled = true))

        assertEquals(UiState.Content(SettingsContent(darkThemeEnabled = true)), viewModel.uiState.value)
    }
}

package com.example.sample.ui.component

